import {historyRows,score,differences,bestSources,illustrative,visiblePlatts,pumpValues,cycleContext} from './model.js';
const $=id=>document.getElementById(id);
const num=(v,d=0)=>Number.isFinite(v)?new Intl.NumberFormat('vi-VN',{minimumFractionDigits:d,maximumFractionDigits:d}).format(v):'—';
const sign=(v,d=0)=>Number.isFinite(v)?(v>0?'+':'')+num(v,d):'—';
const date=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'chưa có';
const day=v=>v?v.split('-').reverse().join('/'):'—';
const el=(tag,text,cls)=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
function row(body,values){const tr=document.createElement('tr');values.forEach((v,i)=>tr.append(el(i===0?'th':'td',v)));$(body).append(tr);return tr;}
function sourceStatus(s,key){const v=s.sources?.[key];return v?.status==='error'?` · LỖI NGUỒN: ${v.error}. Giữ số cũ; lần thử: ${date(v.lastAttemptAt)}`:v?.status==='ok'?' · Lấy nguồn thành công':' · Chưa kiểm tra nguồn';}
function averages(s){const cycle=cycleContext(s),c=cycle.current;$('average-title').textContent=`Bình quân kỳ hiện tại · ${c.count}/${c.expected} phiên quan sát`;$('average-period').textContent=`Từ ${day(c.from)} đến trước ${day(c.until)} · `+(c.missingDates.length?'Chưa có: '+c.missingDates.map(day).join(', '):'Đã có các ngày làm việc trong khoảng');visiblePlatts.forEach((name,i)=>{const d=el('div','');d.append(el('span',name==='DO 10ppm'?'DO 10ppm · 0,001%S':name),el('strong',num(c.values[i],2)));$('averages').append(d);});}
function validate(s){if(s.schemaVersion!==2||!s.official?.prices||!s.pump?.items||!s.platts?.items||!s.forecast?.sources||!Array.isArray(s.history)||s.history.length!==10)throw Error('Snapshot không đúng cấu trúc');if(s.platts.items.length!==12||s.forecast.sources.length!==5)throw Error('Snapshot thiếu sản phẩm hoặc nguồn');return s;}
function render(s){validate(s);['pump-prices','platts-rows','averages','forecast-rows','history-rows','source-errors'].forEach(id=>$(id).replaceChildren());$('snapshot').textContent='SNAPSHOT · cập nhật lúc '+date(s.capturedAt)+' · UTC+7';$('pump-time').textContent='Áp dụng từ '+date(s.pump.effectiveAt);const pump=pumpValues(s);['E5 RON 92-II','E10 RON 95-III','DO 0,05S-II','DO 0,001S-V · 10ppm'].forEach((name,i)=>{const d=el('div','');d.append(el('span',name),el('strong',num(pump[i])));$('pump-prices').append(d);});$('platts-time').textContent=`Ngày chốt: ${day(s.platts.date)} · Lấy số: ${date(s.platts.capturedAt)} · Trang cập nhật: ${date(s.platts.pageUpdatedAt)}${s.platts.pageUpdatedKind==='article-metadata'?' (metadata bài viết)':''}${sourceStatus(s,'platts')}`;s.platts.items.filter(x=>visiblePlatts.includes(x.name)).forEach(x=>{const change=Number.isFinite(x.value)&&Number.isFinite(x.previous)&&x.value!==0&&x.previous!==0?x.value-x.previous:null;const tr=row('platts-rows',[x.name==='DO 10ppm'?'DO 10ppm · 0,001%S':x.name,num(x.value===0?null:x.value,2),x.unit||'—',sign(change,2)]);tr.lastElementChild.className=change<0?'down':change>0?'up':'';});$('wti-price').textContent=num(s.wti.price,2);const delta=Number.isFinite(s.wti.previous?.price)?s.wti.price-s.wti.previous.price:null;$('wti-change').textContent=delta===null?'Chưa có lần kiểm tra trực tiếp trước để so sánh':sign(delta,2)+' USD so với lần kiểm tra trước';$('wti-change').className=delta<0?'down':delta>0?'up':'';$('wti-time').textContent='Lấy số: '+date(s.wti.capturedAt)+(s.wti.previous?' · Lần trước: '+num(s.wti.previous.price,2)+' lúc '+date(s.wti.previous.capturedAt):'');$('wti-market-time').textContent='Giờ giao dịch Yahoo: '+date(s.wti.marketTime);$('wti-status').textContent=(s.wti.isSample?'ĐANG GIỮ DỮ LIỆU MẪU. ':'')+sourceStatus(s,'wti');if(s.wti.marketTime&&Date.now()-Date.parse(s.wti.marketTime)>72*3600000)$('wti-status').textContent+=' · Giá thị trường đã quá 72 giờ.';averages(s);$('forecast-title').textContent='Dự kiến kỳ '+day(s.forecast.period);$('forecast-time').textContent='Chợ Giá · Lấy số: '+date(s.forecast.capturedAt)+' · Trang cập nhật: '+date(s.forecast.pageUpdatedAt)+(s.forecast.pageUpdatedKind==='article-metadata'?' (metadata bài viết, không phải giờ bản tin)':'')+sourceStatus(s,'forecast');const outdated=s.forecast.basisDate&&s.forecast.basisDate<s.forecast.baseEffectiveAt?.slice(0,10);$('forecast-basis').textContent=`Mốc cộng minh họa: giá trần hiệu lực ${date(s.forecast.baseEffectiveAt)}. `+(outdated?`CẢNH BÁO: Chợ Giá dùng giá thành phẩm ${day(s.forecast.basisDate)}, trước kỳ điều chỉnh ${day(s.forecast.baseEffectiveAt.slice(0,10))}. Mức dự báo chưa cập nhật theo mốc giá mới; phép cộng chỉ minh họa, không ghi nhận để chấm độ chính xác.`:'Dự báo chỉ để tham khảo; chưa phải quyết định giá.');for(const x of s.forecast.sources){const tr=row('forecast-rows',[x.name+(x.isSample?' · mẫu':''),...x.deltas.map((v,i)=>v==null?'—':sign(v)+' → '+num(illustrative(s.forecast.base[i],v)))]);x.deltas.forEach((v,i)=>tr.children[i+1].className=v<0?'down':v>0?'up':'');}row('forecast-rows',['Giá thật',...(s.forecast.actual||[null,null,null,null]).map(v=>num(v))]);$('pending-forecast').textContent=Date.now()>=Date.parse(s.forecast.period+'T15:00:00+07:00')?'Kỳ dự kiến đã đến giờ chốt. Chờ chủ trạm nhập công bố chính thức; không tự đổi Giá thật.':s.pendingForecast?`Nguồn có bản tin kỳ ${day(s.pendingForecast.period)}. Chờ chủ trạm xác nhận công bố kỳ hiện tại để chuyển kỳ; không tự sửa Giá thật.`:'';for(const x of historyRows(s.history)){const pred=x.predictions['T-Roo'];const tr=el('tr','');const values=[day(x.period)+(x.isSample?' · mẫu':''),x.actual?x.actual.map(v=>num(v)).join(' / '):'—',pred?pred.map(v=>num(v)).join(' / '):'—',num(score(x.actual,pred),1),bestSources(x).join(', ')||'—'];values.forEach((v,i)=>tr.append(el(i===0?'th':'td',v)));$('history-rows').append(tr);if(Object.keys(x.predictions).length){const detail=el('tr',''),td=el('td','');td.colSpan=5;const box=el('details','');box.append(el('summary','Xem sai lệch từng nguồn · '+day(x.period)));for(const [name,prediction] of Object.entries(x.predictions)){const ds=differences(x.actual,prediction);box.append(el('p',name+': E5 / E10 / DO = '+(ds?ds.map(v=>sign(v)).join(' / '):'—')+' · MAE '+num(score(x.actual,prediction),1)));}td.append(box);detail.append(td);$('history-rows').append(detail);}}
for(const [k,title] of [['platts','Platts'],['forecast','Dự báo Chợ Giá'],['wti','Yahoo WTI']]){const state=s.sources?.[k];$('source-errors').append(el('p',title+': '+(state?.status==='ok'?'OK':'Lỗi / chưa lấy được')+' · thử lúc '+date(state?.lastAttemptAt)+(state?.error?' · '+state.error:'')));}
$('sample-banner').textContent=(s.platts.isSample||s.wti.isSample||s.forecast.sources.some(x=>x.isSample))?'SNAPSHOT CÓ DỮ LIỆU MẪU / NGUỒN CHƯA LẤY ĐƯỢC — xem trạng thái từng nguồn.':'SNAPSHOT · Chỉ đọc bản dữ liệu đã xuất bản, không phải bảng giá trực tiếp.';$('operations').textContent=s.operations?.schedulerActive?'Lịch lấy nguồn tự động đã kích hoạt.':'Lịch tự động CHƯA KÍCH HOẠT · đã có mã workflow, cần repo GitHub và hosting phù hợp. Link này đang là bản test.';
}
async function load(){const b=$('reload');b.disabled=true;try{const r=await fetch('./snapshot.json',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const s=validate(await r.json());render(s);document.dispatchEvent(new CustomEvent('snapshot-loaded',{detail:s}));$('status').textContent='Đã đọc snapshot xuất bản · lần kiểm tra nguồn: '+date(s.lastCheckedAt)+'.';}catch(e){$('status').textContent='Không tải được snapshot. Giữ nguyên dữ liệu đang hiển thị. '+e.message;}finally{b.disabled=false;}}
$('reload').addEventListener('click',load);load();

